/* @lc app=leetcode id=2983 lang=kotlin */ class Solution { fun pc(s: String) = Array(26) { c -> s.runningFold(0) { a, ch -> a + if (ch - 'a' == c) 1 else 0 }.toIntArray() } fun cn(p: Array<IntArray>, l: Int, r: Int) = List(26) { c -> if (l > r) 0 else p[c][r + 1] - p[c][l] } fun ok(p1: Array<IntArray>, p2: Array<IntArray>, l1: Int, r1: Int, l2: Int, r2: Int): Boolean = if (r1 < l2) cn(p1, l1, r1) == cn(p2, l1, r1) && cn(p1, l2, r2) == cn(p2, l2, r2) else if (r2 <= r1) cn(p1, l1, r1) == cn(p2, l1, r1) else cn(p1, l1, r1).zip(cn(p2, l1, l2 - 1)) { a, b -> a - b }.let { d1 -> cn(p2, l2, r2).zip(cn(p1, r1 + 1, r2)) { a, b -> a - b }.let { d2 -> d1.all { it >= 0 } && d2.all { it >= 0 } && d1 == d2 } } fun mm(pm: List<Int>, l: Int, r: Int) = if (l > r) 0 else pm[r + 1] - pm[l] fun canMakePalindromeQueries(s: String, queries: Array<IntArray>): BooleanArray = (s.length / 2).let { h -> s.take(h).let { s1 -> s.drop(h).reversed().let { s2 -> pc(s1).let { p1 -> pc(s2).let { p2 -> (0 until h).runningFold(0) { a, i -> a + if (s1[i] != s2[i]) 1 else 0 }.let { pm -> queries.map { (a, b, c, d) -> (s.length - 1 - d).let { l2 -> (s.length - 1 - c).let { r2 -> pm[h] == mm(pm, a, b) + mm(pm, l2, r2) - mm(pm, maxOf(a, l2), minOf(b, r2)) && (if (a <= l2) ok(p1, p2, a, b, l2, r2) else ok(p2, p1, l2, r2, a, b)) } } }.toBooleanArray() } } } } } } }